"""Private reference review; only the report is written to the agent workspace."""
import json
import os
from pathlib import Path

REPO = Path(os.environ.get("BENCH_REPO_ROOT", "/app/repo"))
APP = Path(os.environ.get("BENCH_APP_ROOT", "/app"))
REPORT = json.loads("{\"schema_version\":2,\"reviews\":[{\"candidate\":\"cedar\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/cedar/limits.py\",\"line\":2},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"config\":{}},\"expected\":{\"timeout\":30}},{\"input\":{\"config\":{\"timeout\":0}},\"expected\":{\"timeout\":0}},{\"input\":{\"config\":{\"timeout\":15},\"override\":{\"timeout\":0}},\"expected\":{\"timeout\":0}},{\"input\":{\"config\":{\"timeout\":12},\"override\":{\"timeout\":null}},\"expected\":{\"timeout\":null}},{\"input\":{\"config\":{\"timeout\":false}},\"expected\":{\"timeout\":false}},{\"input\":{\"config\":{\"timeout\":\"\"}},\"expected\":{\"timeout\":\"\"}},{\"input\":{\"config\":{\"timeout\":10},\"override\":{\"timeout\":5}},\"expected\":{\"timeout\":5}},{\"input\":{\"config\":{\"timeout\":{\"seconds\":0}},\"override\":{\"timeout\":[]}},\"expected\":{\"timeout\":[]}}]},{\"candidate\":\"maple\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/maple/limits.py\",\"line\":2},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"config\":{}},\"expected\":{\"timeout\":30}},{\"input\":{\"config\":{\"timeout\":0}},\"expected\":{\"timeout\":0}},{\"input\":{\"config\":{\"timeout\":15},\"override\":{\"timeout\":0}},\"expected\":{\"timeout\":0}},{\"input\":{\"config\":{\"timeout\":12},\"override\":{\"timeout\":null}},\"expected\":{\"timeout\":null}},{\"input\":{\"config\":{\"timeout\":false}},\"expected\":{\"timeout\":false}},{\"input\":{\"config\":{\"timeout\":\"\"}},\"expected\":{\"timeout\":\"\"}},{\"input\":{\"config\":{\"timeout\":10},\"override\":{\"timeout\":5}},\"expected\":{\"timeout\":5}},{\"input\":{\"config\":{\"timeout\":{\"seconds\":0}},\"override\":{\"timeout\":[]}},\"expected\":{\"timeout\":[]}}]},{\"candidate\":\"birch\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"config\":{}},\"expected\":{\"timeout\":30}},{\"input\":{\"config\":{\"timeout\":0}},\"expected\":{\"timeout\":0}},{\"input\":{\"config\":{\"timeout\":15},\"override\":{\"timeout\":0}},\"expected\":{\"timeout\":0}},{\"input\":{\"config\":{\"timeout\":12},\"override\":{\"timeout\":null}},\"expected\":{\"timeout\":null}},{\"input\":{\"config\":{\"timeout\":false}},\"expected\":{\"timeout\":false}},{\"input\":{\"config\":{\"timeout\":\"\"}},\"expected\":{\"timeout\":\"\"}},{\"input\":{\"config\":{\"timeout\":10},\"override\":{\"timeout\":5}},\"expected\":{\"timeout\":5}},{\"input\":{\"config\":{\"timeout\":{\"seconds\":0}},\"override\":{\"timeout\":[]}},\"expected\":{\"timeout\":[]}}]},{\"candidate\":\"willow\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"config\":{}},\"expected\":{\"timeout\":30}},{\"input\":{\"config\":{\"timeout\":0}},\"expected\":{\"timeout\":0}},{\"input\":{\"config\":{\"timeout\":15},\"override\":{\"timeout\":0}},\"expected\":{\"timeout\":0}},{\"input\":{\"config\":{\"timeout\":12},\"override\":{\"timeout\":null}},\"expected\":{\"timeout\":null}},{\"input\":{\"config\":{\"timeout\":false}},\"expected\":{\"timeout\":false}},{\"input\":{\"config\":{\"timeout\":\"\"}},\"expected\":{\"timeout\":\"\"}},{\"input\":{\"config\":{\"timeout\":10},\"override\":{\"timeout\":5}},\"expected\":{\"timeout\":5}},{\"input\":{\"config\":{\"timeout\":{\"seconds\":0}},\"override\":{\"timeout\":[]}},\"expected\":{\"timeout\":[]}}]}]}")

def main():
    candidates = json.loads((REPO / "candidates.json").read_text())["candidates"]
    assert set(candidates) == {row["candidate"] for row in REPORT["reviews"]}
    APP.mkdir(parents=True, exist_ok=True)
    (APP / "review.json").write_text(json.dumps(REPORT, ensure_ascii=False, allow_nan=False, indent=2) + "\n", encoding="utf-8")

if __name__ == "__main__":
    main()

